import * as THREE from'three';
export function createGlove102(){const root=new THREE.Group();root.name='Guante_de_trabajo_articulado102';const cloth=new THREE.MeshStandardMaterial({name:'Panel textil del guante',color:'#a6b4ba',roughness:.92}),grip=new THREE.MeshStandardMaterial({color:'#24353d',roughness:.95}),cuff=new THREE.MeshStandardMaterial({color:'#d29d3c',roughness:.9}),steel=new THREE.MeshStandardMaterial({color:'#b9c4c9',metalness:.8,roughness:.3}),red=new THREE.MeshStandardMaterial({color:'#bc4a37',roughness:.65});const add=(g,m,x,y,z,sx=1,sy=1,sz=1,parent=root)=>{const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);parent.add(o);return o;};const sphere=new THREE.SphereGeometry(1,16,12);add(sphere,cloth,0,0,0,.061,.079,.026);add(sphere,grip,0,-.005,.020,.050,.062,.010);add(new THREE.CylinderGeometry(.044,.049,.055,16),cuff,0,-.082,0);add(new THREE.CylinderGeometry(.049,.061,.23,16),grip,0,-.21,-.012);for(const y of[-.10,-.085,-.07])add(new THREE.TorusGeometry(.045,.002,4,20),grip,0,y,0).rotation.x=Math.PI/2;const fingers=[];for(let i=0;i<5;i++){const joint=new THREE.Group();joint.position.set(i===4?-.061:-.045+i*.029,i===4?-.01:.052,i===4?.004:0);if(i===4)joint.rotation.z=.78;root.add(joint);const list=[];let parent=joint;for(let j=0;j<3;j++){const bone=new THREE.Group();if(j)bone.position.y=.032;parent.add(bone);add(new THREE.CapsuleGeometry(i===4?.013:.011,.021,4,8),j===2?grip:cloth,0,.016,0,1,1,1,bone);list.push(bone);parent=bone;}fingers.push(list);}const tool=new THREE.Group();root.add(tool);const driver=add(new THREE.CylinderGeometry(.007,.007,.22,10),steel,.018,.19,.02);add(new THREE.CapsuleGeometry(.02,.06,4,10),red,.018,.065,.02);tool.add(driver);const handle=root.children.at(-1);if(handle!==tool)tool.add(handle);const wrench=add(new THREE.BoxGeometry(.026,.22,.014),steel,.018,.15,.02);const ring=add(new THREE.TorusGeometry(.027,.008,6,12),steel,.018,.275,.02);const probe=add(new THREE.CylinderGeometry(.006,.006,.20,10),red,.018,.18,.02);let active='hand';return{root,fingers,set(toolName,closed=false){active=toolName;tool.visible=toolName==='screwdriver';wrench.visible=ring.visible=toolName==='wrench';probe.visible=toolName==='meter';for(let i=0;i<fingers.length;i++)for(let j=0;j<3;j++)fingers[i][j].rotation.x=closed||toolName!=='hand'?.65+(j*.22):.10;root.rotation.z=closed?-.16:-.28;},tip(){return new THREE.Vector3(.018,active==='hand'?.16:active==='wrench'?.31:active==='meter'?.28:.30,.02);}};}
